# Kaggle GPU job: renders "The Infinite Glowing Marble Journey" (generated by .github/workflows/marble.yml)
import os, subprocess, sys, time, glob, shutil, urllib.request
MODE, SAMPLES = "__MODE__", "__SAMPLES__"
SCRIPT = r'''__SCRIPT__'''
W = "/kaggle/working"; os.chdir("/kaggle/tmp" if os.path.isdir("/kaggle/tmp") else "/tmp")
open("marble_run.py", "w").write(SCRIPT)
def sh(c): print("$", c, flush=True); return subprocess.call(c, shell=True)
blender = None
for v in ["5.3.0", "5.2.4", "5.2.3", "5.1.2"]:
    mm = ".".join(v.split(".")[:2])
    url = f"https://download.blender.org/release/Blender{mm}/blender-{v}-linux-x64.tar.xz"
    if sh(f"wget -q {url} -O b.tar.xz && tar xf b.tar.xz") == 0:
        blender = os.path.abspath(f"blender-{v}-linux-x64/blender"); print("Blender", v); break
assert blender, "Blender download failed"
sh("apt-get -qq install -y libxkbcommon0 libsm6 libxi6 libxxf86vm1 libxfixes3 libxrender1 libgl1 >/dev/null 2>&1 || true")
sh("nvidia-smi --query-gpu=name,driver_version --format=csv")
rng = "--start 5280 --end 6000" if MODE == "test" else ""
t = time.time()
rc = sh(f"{blender} -b -P marble_run.py -- --engine cycles --gpu --samples {SAMPLES} --out frames/ {rng} 2>&1 | grep -E 'Saved|Time|gpu|path\\]|scene\\]|Error|rror' ")
n = len(glob.glob("frames/*.jpg")); print(f"{n} frames in {(time.time()-t)/60:.1f} min", flush=True)
ff = shutil.which("ffmpeg")
if not ff:
    sh("pip install -q imageio-ffmpeg"); import imageio_ffmpeg; ff = imageio_ffmpeg.get_ffmpeg_exe()
first = sorted(glob.glob("frames/*.jpg"))[0].split("/")[-1][:5]
out = f"{W}/marble_journey_{MODE}.mp4"
sh(f'{ff} -y -loglevel error -framerate 60 -start_number {int(first)} -i frames/%05d.jpg '
   f'-vf "scale=2160:3840:flags=lanczos" -c:v libx264 -preset slow -crf 18 -pix_fmt yuv420p -movflags +faststart {out}')
print("DONE", out, os.path.getsize(out) // 2**20, "MB")
